#!/usr/bin/env bash
# Builds the paste-safe staging kit for policy B from the same files the
# isolated database runs, so staging and the local runs cannot drift.
# Output: scripts/db-verify/staging/policy-b/S00..S09 (plain SQL, no psql
# meta-commands). Each step is meant to be run, in order, through Lovable's
# SQL tool on a NEW, EMPTY staging project; see ADMIN_V2_RELEASE_READINESS.md 10.10.
#
#   scripts/db-verify/staging/build-policy-b-kit.sh
set -euo pipefail
cd "$(dirname "$0")/../../.."
OUT=scripts/db-verify/staging/policy-b
mkdir -p "$OUT"
header() { printf -- '-- Policy B staging kit, step %s. Generated by scripts/db-verify/staging/build-policy-b-kit.sh\n-- from %s. Do not edit; rebuild. Staging only: never run against the production project.\n\n' "$1" "$2"; }
cat_files() { for f in "$@"; do printf -- '-- ===== %s =====\n' "$f"; cat "$f"; printf '\n'; done; }
guard() { cat scripts/db-verify/staging/guard.sql; printf '\n'; }

{ header S00 "scripts/db-verify/staging/isolation_check.sql"; cat scripts/db-verify/staging/isolation_check.sql; } > "$OUT/S00_isolation_check.sql"
{ header S01 "the hosted pre-state"; guard; cat_files scripts/db-verify/01_prestate.sql; } > "$OUT/S01_hosted_prestate.sql"
{ header S02 "the three applied Administration V2 migrations, verbatim"; guard; cat_files supabase/migrations/20261029000000_admin_v2_policy_apply.sql supabase/migrations/20261029001000_admin_v2_settings_authority.sql supabase/migrations/20261029120000_fix_fee_preview_warnings.sql; } > "$OUT/S02_applied_migrations.sql"
{ header S03 "the case harness and synthetic fixtures"; guard; cat_files scripts/db-verify/02_harness.sql scripts/db-verify/03_fixture.sql scripts/db-verify/04_fee_basis_fixture.sql
  printf "CREATE TABLE t.fp_before AS SELECT p.proname::text AS name, md5(pg_get_functiondef(p.oid)) || ':' || coalesce(p.proacl::text, 'default') AS fp FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('admin_doc_fee_change_preview', 'admin_doc_fee_change_apply', 'merge_dealer_settings', 'recalc_tenant_doc_fee');\n"; } > "$OUT/S03_harness_and_fixtures.sql"
{ header S04 "the deployed-behaviour cases"; guard; printf "UPDATE t.config SET stage = 'fee conflict (deployed)';\n"; cat_files scripts/db-verify/31_fee_conflict_deployed.sql; } > "$OUT/S04_deployed_cases.sql"
{ header S05 "the proposed migration, verbatim"; guard; cat_files supabase/proposed/20261031000000_doc_fee_basis_policy_b.sql; } > "$OUT/S05_policy_b.sql"
{ header S06 "the policy B cases"; guard; printf "UPDATE t.config SET stage = 'policy B';\n"; cat_files scripts/db-verify/30_fee_basis.sql; } > "$OUT/S06_policy_b_cases.sql"
{ header S07 "results"; cat scripts/db-verify/staging/results.sql; } > "$OUT/S07_results.sql"
{ header S08 "the rollback, verbatim"; guard; cat_files supabase/proposed/20261031000000_doc_fee_basis_policy_b.rollback.sql; } > "$OUT/S08_rollback.sql"
{ header S09 "the rollback check"; cat scripts/db-verify/staging/rollback_check.sql; } > "$OUT/S09_rollback_check.sql"
if grep -nE '^\s*\\' "$OUT"/*.sql; then echo "psql meta-command found in the kit" >&2; exit 1; fi
ls -1 "$OUT"
